<?php
$id=$page==='employee-edit'?(int)($_GET['id']??0):0;$v=$id?foundation_employee($pdo,$id):['employment_type'=>'Full Time','employment_status'=>'Active'];if(!$v){echo '<div class="alert error">Employee not found.</div>';return;}if($error&&($_POST['action']??'')==='save_employee')$v=$_POST;
$departments=$pdo->query('SELECT id,name FROM departments WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$designations=$pdo->query('SELECT id,name,department_id FROM designations WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$roles=$pdo->query('SELECT id,name,slug FROM roles WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$managers=$pdo->query('SELECT id,name FROM users WHERE active=1 AND id<>'.(int)$id.' ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
if(!$departments||!$designations):?><div class="alert error">Create an active department and designation in Company Settings before saving an employee.</div><?php endif;?>
<form method="post" enctype="multipart/form-data"><?php ftoken();?><input type="hidden" name="action" value="save_employee"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="version" value="<?=(int)($v['version']??0)?>"><section class="card"><div class="card-heading"><h2>Personal details</h2></div><div class="form-grid three"><?php field('first_name','First name',$v,'text',true,80);field('middle_name','Middle name',$v,'text',false,100);field('last_name','Last name',$v,'text',true,80);field('birth_date','Date of birth',$v,'date');choose('gender','Gender',$v,['','Female','Male','Non-binary','Prefer not to say']);choose('blood_group','Blood group',$v,['','A+','A-','B+','B-','AB+','AB-','O+','O-','Unknown']);?><label class="full">Profile photo<input type="file" name="photo" accept="image/jpeg,image/png"><span class="hint">JPEG or PNG · up to 2 MB. Leave blank to keep the current photo.</span></label></div></section>
<section class="card"><div class="card-heading"><h2>Employment & access</h2></div><div class="form-grid three"><?php field('employee_code','Employee ID (optional)',$v,'text',false,60);field('email','Work email',$v,'email');field('username','Username (blank generates first.last)',$v);?><label>Department *<select name="department_id" data-dependent required><option value="">Select department</option><?php foptions($departments,$v['department_id']??'');?></select></label><label>Designation *<select name="designation_id" required><option value="">Select designation</option><?php foreach($designations as $d):?><option value="<?=$d['id']?>" data-department="<?=$d['department_id']??''?>" <?=($v['designation_id']??'')==$d['id']?'selected':''?>><?=h($d['name'])?></option><?php endforeach;?></select></label><label>Role *<select name="role_id" required><?php foreach($roles as $r):if(!can($pdo,$user,'roles.edit')&&$r['slug']!=='employee'&&($v['role_id']??0)!=$r['id'])continue;?><option value="<?=$r['id']?>" <?=isset($v['role_id'])?($v['role_id']==$r['id']?'selected':''):($r['slug']==='employee'?'selected':'')?>><?=h($r['name'])?></option><?php endforeach;?></select></label><label>Reporting manager<select name="manager_id"><option value="">Not assigned</option><?php foptions($managers,$v['manager_id']??'');?></select></label><?php field('joining_date','Joining date',$v,'date',true);choose('employment_type','Employment type',$v,['Full Time','Part Time','Contract','Intern','Probation']);choose('employment_status','Employment status',$v,['Active','Inactive','Notice Period','Resigned','Terminated']);if(!$id):?><label>Initial password<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password"><span class="hint">Leave blank for User@123. A password change is required at first sign-in.</span></label><?php endif;?></div><p class="hint">Inactive, Resigned and Terminated statuses disable login. Reactivation is a separate action on the employee profile.</p></section>
<section class="card"><div class="card-heading"><h2>Contact & address</h2></div><div class="form-grid three"><?php field('personal_email','Personal email',$v,'email');field('mobile','Mobile number',$v,'tel',false,40);field('alternate_phone','Alternate phone',$v,'tel',false,40);foreach(['current_address'=>'Current address','permanent_address'=>'Permanent address'] as $k=>$label):?><label class="full"><?=$label?><textarea name="<?=$k?>" maxlength="2000"><?=h($v[$k]??'')?></textarea></label><?php endforeach;foreach(['city'=>'City','state'=>'State','country'=>'Country','pin_code'=>'Postal code'] as $k=>$label)field($k,$label,$v,'text',false,$k==='pin_code'?20:100);?></div></section>
<section class="card"><div class="card-heading"><h2>Emergency contact</h2></div><div class="form-grid three"><?php field('emergency_name','Contact name',$v,'text',false,150);field('emergency_phone','Contact number',$v,'tel',false,40);field('emergency_relationship','Relationship',$v,'text',false,80);?></div></section><div class="form-actions"><a class="button" href="?page=<?=$id?'employee-view&id='.$id:'employees'?>">Cancel</a><button class="button primary">Save employee</button></div></form>
